import{_ as t,c as o,a5 as a,o as s}from"./chunks/framework.DoP1wijR.js";const i="/pub-blog/assets/image-20250310014455245.CTuNTY4e.png",n="/pub-blog/assets/image-20250310014629433.BxQBRucy.png",r="data:image/png;base64,",p="/pub-blog/assets/image-20250310014837997.BtVcu2JQ.png",d="/pub-blog/assets/image-20250310014857033.BIDkQOeU.png",g="data:image/png;base64,",A="/pub-blog/assets/image-20250310015150136.DVF0kSuQ.png",l="/pub-blog/assets/image-20250310015404382.qg9nH8IX.png",c="/pub-blog/assets/image-20250310020254575.5ormwTdF.png",m="/pub-blog/assets/image-20250310021016941.DlkxIOL7.png",u="/pub-blog/assets/image-20250310020405900.03bIvrto.png",b="/pub-blog/assets/image-20250310021218929.Dlmj3wSt.png",k="/pub-blog/assets/image-20250310021328772.D3_Wp4nN.png",h="/pub-blog/assets/image-20250310021847340.BfHhjWoq.png",S="/pub-blog/assets/image-20250310022006247.opJotZsy.png",L=JSON.parse('{"title":"喜大普奔 DevEco Studio 官方接 入 DeepSeek 了","description":"","frontmatter":{},"headers":[],"relativePath":"鸿蒙开发技巧/DevEco Studio 官方接入DeepSeek了/DevEco Studio 官方接入DeepSeek了.md","filePath":"鸿蒙开发技巧/DevEco Studio 官方接入DeepSeek了/DevEco Studio 官方接入DeepSeek了.md","lastUpdated":1745085728000}'),I={name:"鸿蒙开发技巧/DevEco Studio 官方接入DeepSeek了/DevEco Studio 官方接入DeepSeek了.md"};function D(v,e,q,C,f,E){return s(),o("div",null,e[0]||(e[0]=[a('<h1 id="喜大普奔-deveco-studio-官方接-入-deepseek-了" tabindex="-1">喜大普奔 DevEco Studio 官方接 入 DeepSeek 了 <a class="header-anchor" href="#喜大普奔-deveco-studio-官方接-入-deepseek-了" aria-label="Permalink to &quot;喜大普奔 DevEco Studio 官方接 入 DeepSeek 了&quot;">​</a></h1><p><strong>喜大普奔</strong>，最新版本 DevEco Studio 的 AI 工具 CodeGenie 接入 DeepSeek，随着各种 AI 工具的快速发展，CodeGenie 的 DeepSeek 接入</p><p>可谓是姗姗来迟了。</p><h2 id="效果一览" tabindex="-1">效果一览 <a class="header-anchor" href="#效果一览" aria-label="Permalink to &quot;效果一览&quot;">​</a></h2><p>先来看一眼接入的效果模样：</p><p><img src="'+i+'" alt="image-20250310014455245"></p><p>接下来我们来看一下如何进行接入！</p><h2 id="要求的软件版本" tabindex="-1">要求的软件版本 <a class="header-anchor" href="#要求的软件版本" aria-label="Permalink to &quot;要求的软件版本&quot;">​</a></h2><ol><li><strong>DevEco Studio</strong></li></ol><p><img src="'+n+'" alt="image-20250310014629433"></p><ol start="2"><li><p><strong>CodeGenie</strong></p><p><img src="'+r+'" alt="image-20250310014723218"></p></li></ol><p>下载地址都可以在官网中获取</p><ol><li><p><strong>DevEco Studio</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://developer.huawei.com/consumer/cn/download/deveco-studio</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="'+p+'" alt="image-20250310014837997"></p></li><li><p><strong>CodeGenie</strong></p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://developer.huawei.com/consumer/cn/download/deveco-codegenie</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="'+d+'" alt="image-20250310014857033"></p></li></ol><h2 id="安装-codegenie-步骤" tabindex="-1">安装 CodeGenie 步骤 <a class="header-anchor" href="#安装-codegenie-步骤" aria-label="Permalink to &quot;安装 CodeGenie 步骤&quot;">​</a></h2><ol><li><p>下载<strong>CodeGenie</strong> 插件，<em>不用解压</em></p><p><img src="'+g+'" alt="image-20250310015026848"></p></li><li><p><strong>DevEco Studio</strong> 中安装</p><blockquote><p>文件-&gt;设置-&gt;插件-&gt;设置-&gt;从磁盘安装插件， 然后重启</p></blockquote><p><img src="'+A+'" alt="image-20250310015150136"></p></li></ol><h2 id="codegenie-实用功能" tabindex="-1">CodeGenie 实用功能 <a class="header-anchor" href="#codegenie-实用功能" aria-label="Permalink to &quot;CodeGenie 实用功能&quot;">​</a></h2><p><strong>CodeGenie</strong> 目前提供的主要功能有：</p><ol><li><strong>智能问答 <em>DeepSeek</em></strong></li><li><strong>编辑器 AI 代码提示</strong></li><li><strong>编译报错智能分析</strong></li><li>万能卡片生成</li></ol><h3 id="智能问答-deepseek" tabindex="-1">智能问答 DeepSeek <a class="header-anchor" href="#智能问答-deepseek" aria-label="Permalink to &quot;智能问答 DeepSeek&quot;">​</a></h3><p>重新打开 <strong>DevEco Studio</strong>后，点击侧边栏的 <strong>CodeGenie</strong>，进行华为账户登录后，便可以实用 <strong>CodeGenie</strong>了，可以在这里调用 DeepSeek。</p><p><img src="'+l+'" alt="image-20250310015404382"></p><p>然后就可以进行智能问答了。</p><p>问：鸿蒙应用开发中，常见的状态装饰器有哪些？</p><p>答：</p><p><img src="'+c+'" alt="image-20250310020254575"></p><h3 id="编辑器-ai-代码提示" tabindex="-1">编辑器 AI 代码提示 <a class="header-anchor" href="#编辑器-ai-代码提示" aria-label="Permalink to &quot;编辑器 AI 代码提示&quot;">​</a></h3><p>当前的<strong>CodeGenie</strong>也支持编辑器内 AI 代码提示。</p><p>默认情况下，开发者可以在代码文件的任意位置使用热键 Alt+X 或 Alt+C 手动触发代码生成，也可以在设置中开启 &quot;片段生成&quot; 或 &quot;行内生成&quot; 选项，AI 将基于代码上下文自动进行续写。</p><p><strong>Alt+X</strong></p><p><img src="'+m+'" alt="image-20250310021016941"></p><p><strong>代码生成的配置</strong></p><p><img src="'+u+'" alt="image-20250310020405900"></p><h3 id="编译报错智能分析" tabindex="-1">编译报错智能分析 <a class="header-anchor" href="#编译报错智能分析" aria-label="Permalink to &quot;编译报错智能分析&quot;">​</a></h3><p>开发中，如果程序出现了编译错误，可以快速的调用 AI 能力进行错误分析。</p><p>示例：将 API 版本由 14 改为 22 <em>22 是不正确的版本</em></p><p><img src="'+b+'" alt="image-20250310021218929"></p><p><strong>执行编译</strong></p><p><img src="'+k+'" alt="image-20250310021328772"></p><p>可以看到，此时 <strong>CodeGenie</strong>边开始思考和分析错误了，然后给出答案</p><p><img src="'+h+'" alt="image-20250310021847340"></p><h3 id="万能卡片生成" tabindex="-1">万能卡片生成 <a class="header-anchor" href="#万能卡片生成" aria-label="Permalink to &quot;万能卡片生成&quot;">​</a></h3><p>万能卡片生成算是<strong>CodeGenie</strong>的常规功能了。</p><p><img src="'+S+'" alt="image-20250310022006247"></p><p>切换到万能卡片选项，参考以下提示词，便可以生成万能卡片代码了。</p><table tabindex="0"><thead><tr><th><strong>序号</strong></th><th><strong>建议描述维度</strong></th><th><strong>说明</strong></th><th><strong>举例</strong></th></tr></thead><tbody><tr><td>1</td><td>卡片用途</td><td>卡片的用途/业务场景，比如电商购物、娱乐、生活服务类等。</td><td>例如“电商购物卡片”、“娱乐类卡片”。</td></tr><tr><td>2</td><td>卡片功能</td><td>卡片包含的组件，如图标、标题、按钮等；组件的状态信息，如图标主题、标题内容、按钮显示的文字等。</td><td>例如“新品上市主标题”、“商品搜索按钮”、“热门电影子板块入口”等。</td></tr><tr><td>3</td><td>卡片尺寸</td><td>HamonyOS 官网提供的四种卡片尺寸：1<em>2（微卡片）、2</em>2（小卡片）、2<em>4（中卡片）、4</em>4（大卡片）；卡片尺寸非必选项，AI 会根据前两个维度描述的信息，智能选择效果最佳的尺寸。</td><td>例如“2*2 尺寸的卡片”、“中卡片”等</td></tr></tbody></table><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>​ 随着 <strong>DeepSeek</strong> 的正式接入，<strong>DevEco Studio</strong> 的 <strong>CodeGenie</strong> 工具实现了从“代码助手”到“开发全流程智能伙伴”的跨越升级。无论是</p><p>通过 <strong>智能问答</strong> 快速解决技术难题，还是借助 <strong>AI 代码提示</strong> 提升编码效率，甚至是利用 <strong>编译报错分析</strong> 精准定位问题，这一系列功能都</p><p>显著降低了鸿蒙应用开发的门槛，让开发者更专注于创新与业务逻辑的实现。<strong>万能卡片生成</strong> 等特色功能，进一步展现了 AI 在垂直场</p><p>景中的实用价值，为鸿蒙生态的多样化开发需求提供了高效解决方案。此次更新不仅是华为在开发者工具领域的一次重要突破，更</p><p>预示着 AI 与 IDE 深度结合的无限潜力。</p><p>​ 建议开发者尽快升级至最新版本，体验 <strong>CodeGenie + DeepSeek</strong> 的协同效能，解锁更智能、更流畅的开发体验。未来，随着 AI 技术的持续迭代，相信鸿蒙生态将迎来更强大的开发工具支持，赋能更多创新应用落地。</p><p><strong>立即行动</strong>：</p><ul><li>下载 DevEco Studio：<a href="https://developer.huawei.com/consumer/cn/download/deveco-studio" target="_blank" rel="noreferrer">官网链接</a></li><li>获取 CodeGenie 插件：<a href="https://developer.huawei.com/consumer/cn/download/deveco-codegenie" target="_blank" rel="noreferrer">插件地址</a></li></ul><p>让 AI 为你的代码插上翅膀，开启高效开发新时代！🚀</p>',55)]))}const J=t(I,[["render",D]]);export{L as __pageData,J as default};
